SELECT Students.DeletedOn, Students.CC, Students.[DS#], Family.FormID, Students.Name, Students.CurrentClass, Students.CurrentSection, Family.FatherName, Family.Mobile, Family.PhHome, Family.Mcell, Family.EmerNo, Family.PhOffice, Feerecipt.IssueDate, [TuitionFee]+[Mis_fee]+[AdmissionFee]+[other]+[ProspectusFee]+[Fine]+[ExamsFee] AS TOTAL, Feerecipt.ReDate, Feerecipt.Period, Feerecipt.Paid, Students.Status, Feerecipt.[Sr#], Feerecipt.TuitionFee, Feerecipt.ExamsFee, Feerecipt.Mis_fee, Feerecipt.AdmissionFee, Feerecipt.ProspectusFee, Feerecipt.Fine, Feerecipt.Other, Feerecipt.DateEdited, Family.Flag, Departments.DeptNo, "92" & Right([Mobile],10) AS cellno, Feerecipt.duedate, Feerecipt.RecipNo, Feerecipt.ReceivedAmount, Feerecipt.DRCR, Feerecipt.Description, Departments.AccountNumber, Departments.CampusDivision, Classes.ClassNam, Feerecipt.Remarks, Feerecipt.deletedON
FROM Departments INNER JOIN (Family INNER JOIN ((Classes INNER JOIN Students ON Classes.ClassID = Students.CurrentClass) INNER JOIN Feerecipt ON Students.CC = Feerecipt.CC) ON Family.FormID = Students.FamilyID) ON Departments.DeptNo = Classes.DeptNo
WHERE (((Feerecipt.Paid)=False) AND ((Students.Status)=True) AND ((Feerecipt.deletedON)<Date() Or (Feerecipt.deletedON) Is Null))
ORDER BY Students.CurrentClass;

